package com.primehr.rsp.evaluation.api;
import com.primehr.rsp.evaluation.api.EvaluationProceedingDtos.*; import com.primehr.rsp.evaluation.application.*; import com.primehr.security.*; import com.primehr.shared.api.*; import jakarta.validation.*; import org.springframework.http.*; import org.springframework.security.core.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/primehr/v1/rsp/evaluation-proceedings") public class EvaluationProceedingController {private final EvaluationProceedingService service;private final RspCandidateEvaluationPermissionGuard permission;private final AgencyScopeResolver agency;public EvaluationProceedingController(EvaluationProceedingService s,RspCandidateEvaluationPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}@GetMapping public PageResponse<ProceedingResponse> list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam(name="page",defaultValue="0")int page,@RequestParam(name="size",defaultValue="20")int size){permission.require(PrimeHrAction.ACCESS,t);return service.list(agency.resolveAgencyId(a),a.getName(),page,size);}@GetMapping("/{id}")public ProceedingResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){permission.require(PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id,a.getName());}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ProceedingResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody CreateProceeding r){permission.require(PrimeHrAction.ADD,t);return service.create(agency.resolveAgencyId(a),r,a.getName(),c);}@PutMapping("/{id}/candidates")public ProceedingResponse admit(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody AdmitCandidates r){permission.require(PrimeHrAction.ADD,t);return service.admit(agency.resolveAgencyId(a),id,r,a.getName(),c);}@PostMapping("/{id}/open")public ProceedingResponse open(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition r){permission.require(PrimeHrAction.ADD,t);return service.open(agency.resolveAgencyId(a),id,r,a.getName(),c);}@PostMapping("/{id}/cancel")public ProceedingResponse cancel(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition r){permission.require(PrimeHrAction.EDIT,t);return service.cancel(agency.resolveAgencyId(a),id,r,a.getName(),c);}}
